use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let input_str = input.as_str();
    if input_str.is_empty() {
        return serde_json::Value::Null;
    }

    let mut cents = 0;
    let mut has_sign = false;
    let mut has_dot = false;

    for c in input_str.chars() {
        if c == '-' {
            has_sign = true;
        } else if c == '.' {
            has_dot = true;
        } else if c.is_digit(10) {
            if has_dot {
                cents *= 10;
                cents += c.to_digit(10).unwrap();
            } else {
                cents = cents * 100 + c.to_digit(10).unwrap();
            }
            has_dot = false;
        }
    }

    if cents > 1000000 {
        cents = cents % 1000000;
    }

    if has_sign {
        cents = -cents;
    }

    serde_json::Value::Number(cents)
}

fn main() {
    let input = serde_json::Value::from("{\"input\":\"-12.30\",\"expected\":-1230}");
    let result = solve(input);
    println!("{:?}", result);
}
```

